"use strict";
import CurrencyLogo from "components/Logo/CurrencyLogo";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useVotingRewards, formatRewardAmount, groupRewardsByType, getUniqueRewardContracts } from "hooks/useVotingRewards";
import { useClaimRewards } from "hooks/useClaimRewards";
import styled from "styled-components";
import { Flex, SpinningLoader, Text, useSporeColors } from "ui/src";
import { Token } from "@uniswap/sdk-core";
import { UniverseChainId } from "uniswap/src/features/chains/types";
function createTokenFromReward(address, symbol, decimals) {
  return new Token(
    UniverseChainId.AbstractTestnet,
    address,
    decimals,
    symbol,
    symbol
  );
}
export default function RewardTokenAmountDetails({ lock, isLoading }) {
  const colors = useSporeColors();
  const { rewards, canClaim, isLoading: rewardsLoading, error } = useVotingRewards(lock);
  const { fees, bribes } = groupRewardsByType(rewards);
  const claimableContracts = getUniqueRewardContracts(rewards);
  const { claimRewards, isLoading: claimLoading, error: claimError } = useClaimRewards();
  const data = [
    // Fee rewards (from trading fees)
    ...fees.map((fee) => {
      const symbol = fee.symbol === "TOKEN" ? "ABX" : fee.symbol;
      const token = createTokenFromReward(fee.address, symbol, fee.decimals);
      return {
        token,
        amount: formatRewardAmount(fee.amount, fee.decimals),
        symbol,
        type: "Fees",
        tooltip: `${formatRewardAmount(fee.amount, fee.decimals)} ${symbol}`
      };
    }),
    // Bribe rewards (incentives)  
    ...bribes.map((bribe) => {
      const symbol = bribe.symbol === "TOKEN" ? "ABX" : bribe.symbol;
      const token = createTokenFromReward(bribe.address, symbol, bribe.decimals);
      return {
        token,
        amount: formatRewardAmount(bribe.amount, bribe.decimals),
        symbol,
        type: "Incentive",
        tooltip: `${formatRewardAmount(bribe.amount, bribe.decimals)} ${symbol}`
      };
    })
  ];
  if (data.length === 0) {
    const abxToken = createTokenFromReward("0xb6313bE1c20Dc222199EC567951ABc6b5B64DFD6", "ABX", 18);
    const ethToken = createTokenFromReward("0x9edcde0257f2386ce177c3a7fcdd97787f0d841d", "WETH", 18);
    data.push(
      {
        token: abxToken,
        amount: "0",
        symbol: "ABX",
        type: "Fees",
        tooltip: "0 ABX"
      },
      {
        token: ethToken,
        amount: "0",
        symbol: "ETH",
        type: "Fees",
        tooltip: "0 ETH"
      },
      {
        token: abxToken,
        amount: "0",
        symbol: "ABX",
        type: "Incentive",
        tooltip: "0 ABX"
      }
    );
  }
  const ClaimButton = styled.button`
    all: unset;
    display: flex;
    padding: 5px 12px;
    border-radius: 30px;
    background-color: ${colors.surface2.val};
    borderradius: 10px;
    border: 1px solid ${colors.surface3.val};
    transition: all 0.2s ease;
    cursor: ${(props) => props.$canClaim ? "pointer" : "not-allowed"};
    opacity: ${(props) => props.$canClaim ? 1 : 0.6};
    &:hover {
      background-color: ${(props) => props.$canClaim ? colors.surface2Hovered.val : colors.surface2.val};
    }
  `;
  const tokenBreakdown = data.reduce((acc, item) => {
    const amount = parseFloat(item.amount);
    if (amount > 0) {
      if (!acc[item.symbol]) {
        acc[item.symbol] = 0;
      }
      acc[item.symbol] += amount;
    }
    return acc;
  }, {});
  const breakdownText = Object.entries(tokenBreakdown).map(([symbol, amount]) => `${amount.toFixed(4)} ${symbol}`).join(", ") || "0 ABX, 0 ETH";
  return <Flex
    className="right"
    flexDirection="column"
    alignItems="flex-end"
    gap={"$spacing18"}
    $md={{ alignItems: "flex-start" }}
  >
      {
    /* Total rewards display */
  }
      <Flex flexDirection="column" alignItems="flex-end" gap={"$gap4"} $md={{ alignItems: "flex-start" }}>
        <Text variant="body2" fontWeight="600">
          -
        </Text>
        <Text variant="body4" color={"$neutral2"}>
          {breakdownText}
        </Text>
      </Flex>

      <Flex flexDirection="column" alignItems="flex-end" gap={"$gap12"} $md={{ alignItems: "flex-start" }}>
        {data.map((item, index) => <Flex key={index} row alignItems="center" gap={"$gap8"} opacity={isLoading || rewardsLoading ? 0.6 : 1}>
            <MouseoverTooltip text={item.tooltip} size={TooltipSize.Max} placement="top">
              <Flex row alignItems="center" gap={"$gap8"}>
                <CurrencyLogo currency={item.token} size={18} />
                <Text variant="body3">
                  {item.amount} {item.symbol}
                </Text>
              </Flex>
            </MouseoverTooltip>
            <Text
    backgroundColor={"$surface1"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant={"body4"}
    borderWidth={1}
    borderColor={"$surface3"}
  >
              {item.type}
            </Text>
          </Flex>)}
      </Flex>
      <ClaimButton
    $canClaim={canClaim}
    disabled={!canClaim || rewardsLoading || claimLoading}
    onClick={async () => {
      if (canClaim && !rewardsLoading && !claimLoading && lock) {
        const lockId = lock.id ? `#${lock.id.slice(-6)}` : "#Unknown";
        const totalFeesAmount = fees.reduce((sum, fee) => sum + parseFloat(formatRewardAmount(fee.amount, fee.decimals)), 0);
        const totalBribesAmount = bribes.reduce((sum, bribe) => sum + parseFloat(formatRewardAmount(bribe.amount, bribe.decimals)), 0);
        const totalRewardsText = `${totalFeesAmount.toFixed(4)} ABX fees + ${totalBribesAmount.toFixed(4)} ABX incentives`;
        const feeTokens = fees.map((f) => f.address);
        const bribeTokens = bribes.map((b) => b.address);
        try {
          console.log("\u{1F3AF} [VOTING REWARDS] Claiming rewards for lock:", lock?.id);
          const result = await claimRewards({
            tokenId: lock.id,
            feeContracts: claimableContracts.feeContracts,
            bribeContracts: claimableContracts.bribeContracts,
            feeTokens,
            bribeTokens
          });
          if (result.success) {
            popupRegistry.addPopup(
              {
                type: PopupType.ClaimRewardsSuccess,
                content: {
                  type: "success",
                  title: "Voting Rewards Claimed Successfully",
                  description: `Successfully claimed ${totalRewardsText} from veABX lock ${lockId}.`,
                  hash: result.hash,
                  action: "claimRewards",
                  amount: totalRewardsText
                }
              },
              `claim-voting-rewards-success-${lockId}`
            );
          } else {
            throw new Error(claimError || "Unknown error occurred");
          }
        } catch (error2) {
          console.error("Failed to claim voting rewards:", error2);
          popupRegistry.addPopup(
            {
              type: PopupType.ClaimRewardsError,
              content: {
                type: "error",
                title: "Failed to Claim Voting Rewards",
                description: error2 instanceof Error ? error2.message : "An unexpected error occurred while claiming your voting rewards.",
                action: "claimRewards"
              }
            },
            `claim-voting-rewards-error-${lockId}`
          );
        }
      }
    }}
  >
        <Flex row alignItems="center" gap="$gap4">
          {claimLoading && <SpinningLoader size={16} />}
          <Text variant="body3" color={canClaim ? "$neutral1" : "$neutral2"}>
            {claimLoading ? "Claiming" : rewardsLoading ? "Loading" : canClaim ? "Claim" : "No rewards"}
          </Text>
        </Flex>
      </ClaimButton>
    </Flex>;
}
