"use strict";
import { useMemo, useCallback } from "react";
import { useReadContracts, usePublicClient } from "wagmi";
import { formatUnits } from "viem";
import { getContractAddress, getContractAbi, ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const TOKEN_METADATA_CACHE = {
  "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d": { symbol: "WETH", decimals: 18 },
  "0xb6313be1c20dc222199ec567951abc6b5b64dfd6": { symbol: "ABX", decimals: 18 },
  "0x698f98ab816670692fa9dd8e1486ea0fd253e996": { symbol: "USDC", decimals: 18 }
};
export function useVotingRewards(lock) {
  const publicClient = usePublicClient({ chainId: UniverseChainId.AbstractTestnet });
  const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const {
    data: poolData,
    isLoading: poolsLoading,
    error: poolsError,
    refetch: refetchPools
  } = useReadContracts({
    contracts: lock ? [
      // Try to get up to 10 pools (most locks vote for 1-3)
      ...Array.from({ length: 10 }, (_, i) => ({
        address: voterAddress,
        abi: voterAbi,
        functionName: "poolVote",
        args: [BigInt(lock.id), BigInt(i)]
      })),
      // Also get voting weights for verification
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "usedWeights",
        args: [BigInt(lock.id)]
      },
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "lastVoted",
        args: [BigInt(lock.id)]
      }
    ] : [],
    query: {
      enabled: !!lock,
      retry: 3,
      retryDelay: 1e3
    }
  });
  const votedPools = useMemo(() => {
    if (!poolData || !lock) return [];
    const pools = [];
    for (let i = 0; i < 10; i++) {
      const pool = poolData[i]?.result;
      if (pool && pool !== "0x0000000000000000000000000000000000000000") {
        pools.push(pool);
      } else if (poolData[i]?.error) {
        break;
      }
    }
    return pools;
  }, [poolData, lock]);
  const {
    data: gaugeData,
    isLoading: gaugesLoading,
    error: gaugesError
  } = useReadContracts({
    contracts: votedPools.flatMap((pool) => [
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "gauges",
        args: [pool]
      },
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "votes",
        args: [BigInt(lock?.id || 0), pool]
      }
    ]),
    query: {
      enabled: votedPools.length > 0 && !!lock,
      retry: 3,
      retryDelay: 1e3
    }
  });
  const rewardContracts = useMemo(() => {
    if (!gaugeData || votedPools.length === 0) return { pools: [], gauges: [], feeContracts: [], bribeContracts: [] };
    const pools = [];
    const gauges = [];
    const feeContracts2 = /* @__PURE__ */ new Set();
    const bribeContracts2 = /* @__PURE__ */ new Set();
    for (let i = 0; i < votedPools.length; i++) {
      const gaugeIndex = i * 2;
      const votesIndex = i * 2 + 1;
      const gauge = gaugeData[gaugeIndex]?.result;
      const votingWeight = gaugeData[votesIndex]?.result;
      if (gauge && gauge !== "0x0000000000000000000000000000000000000000") {
        pools.push({
          poolAddress: votedPools[i],
          gaugeAddress: gauge,
          votingWeight: votingWeight?.toString() || "0"
        });
        gauges.push(gauge);
      }
    }
    return { pools, gauges, feeContracts: Array.from(feeContracts2), bribeContracts: Array.from(bribeContracts2) };
  }, [gaugeData, votedPools]);
  const {
    data: rewardContractData,
    isLoading: rewardContractsLoading,
    error: rewardContractsError
  } = useReadContracts({
    contracts: rewardContracts.gauges.flatMap((gauge) => [
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "gaugeToBribe",
        args: [gauge]
      },
      {
        address: voterAddress,
        abi: voterAbi,
        functionName: "gaugeToFees",
        args: [gauge]
      }
    ]),
    query: {
      enabled: rewardContracts.gauges.length > 0,
      retry: 3,
      retryDelay: 1e3
    }
  });
  const { feeContracts, bribeContracts } = useMemo(() => {
    if (!rewardContractData || rewardContracts.gauges.length === 0) {
      return { feeContracts: [], bribeContracts: [] };
    }
    const fees = [];
    const bribes = [];
    for (let i = 0; i < rewardContracts.gauges.length; i++) {
      const bribeIndex = i * 2;
      const feeIndex = i * 2 + 1;
      const bribe = rewardContractData[bribeIndex]?.result;
      const fee = rewardContractData[feeIndex]?.result;
      if (bribe && bribe !== "0x0000000000000000000000000000000000000000") {
        bribes.push(bribe);
      }
      if (fee && fee !== "0x0000000000000000000000000000000000000000") {
        fees.push(fee);
      }
    }
    return { feeContracts: fees, bribeContracts: bribes };
  }, [rewardContractData, rewardContracts.gauges]);
  const {
    data: rewardAmounts,
    isLoading: rewardsLoading,
    error: rewardsError,
    refetch: refetchRewards
  } = useReadContracts({
    contracts: [
      // Get reward token lists and amounts for fee contracts
      ...feeContracts.map((contract) => ({
        address: contract,
        abi: [
          {
            inputs: [],
            name: "rewardsListLength",
            outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
            stateMutability: "view",
            type: "function"
          }
        ],
        functionName: "rewardsListLength"
      })),
      // Get reward token lists and amounts for bribe contracts
      ...bribeContracts.map((contract) => ({
        address: contract,
        abi: [
          {
            inputs: [],
            name: "rewardsListLength",
            outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
            stateMutability: "view",
            type: "function"
          }
        ],
        functionName: "rewardsListLength"
      }))
    ],
    query: {
      enabled: (feeContracts.length > 0 || bribeContracts.length > 0) && !!lock,
      retry: 3,
      retryDelay: 1e3
    }
  });
  const rewardTokenContracts = useMemo(() => {
    if (!rewardAmounts) return [];
    const contracts = [];
    let contractIndex = 0;
    for (let i = 0; i < feeContracts.length; i++) {
      const length = rewardAmounts[contractIndex]?.result;
      if (length && length > 0n) {
        for (let j = 0; j < Number(length); j++) {
          contracts.push({
            address: feeContracts[i],
            abi: [
              {
                inputs: [{ internalType: "uint256", name: "", type: "uint256" }],
                name: "rewards",
                outputs: [{ internalType: "address", name: "", type: "address" }],
                stateMutability: "view",
                type: "function"
              }
            ],
            functionName: "rewards",
            args: [BigInt(j)],
            meta: { type: "fee", contractAddress: feeContracts[i], index: j }
          });
        }
      }
      contractIndex++;
    }
    for (let i = 0; i < bribeContracts.length; i++) {
      const length = rewardAmounts[contractIndex]?.result;
      if (length && length > 0n) {
        for (let j = 0; j < Number(length); j++) {
          contracts.push({
            address: bribeContracts[i],
            abi: [
              {
                inputs: [{ internalType: "uint256", name: "", type: "uint256" }],
                name: "rewards",
                outputs: [{ internalType: "address", name: "", type: "address" }],
                stateMutability: "view",
                type: "function"
              }
            ],
            functionName: "rewards",
            args: [BigInt(j)],
            meta: { type: "bribe", contractAddress: bribeContracts[i], index: j }
          });
        }
      }
      contractIndex++;
    }
    return contracts;
  }, [rewardAmounts, feeContracts, bribeContracts]);
  const {
    data: tokenAddresses,
    isLoading: tokenAddressesLoading,
    error: tokenAddressesError
  } = useReadContracts({
    contracts: rewardTokenContracts,
    query: {
      enabled: rewardTokenContracts.length > 0,
      retry: 3,
      retryDelay: 1e3
    }
  });
  const earnedContracts = useMemo(() => {
    if (!tokenAddresses || !lock) return [];
    return tokenAddresses.map((tokenData, index) => {
      const token = tokenData.result;
      const meta = rewardTokenContracts[index]?.meta;
      if (!token || !meta) return null;
      return {
        address: meta.contractAddress,
        abi: [
          {
            inputs: [
              { internalType: "address", name: "token", type: "address" },
              { internalType: "uint256", name: "tokenId", type: "uint256" }
            ],
            name: "earned",
            outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
            stateMutability: "view",
            type: "function"
          }
        ],
        functionName: "earned",
        args: [token, BigInt(lock.id)],
        meta: { ...meta, token }
      };
    }).filter(Boolean);
  }, [tokenAddresses, rewardTokenContracts, lock]);
  const {
    data: earnedAmounts,
    isLoading: earnedLoading,
    error: earnedError
  } = useReadContracts({
    contracts: earnedContracts,
    query: {
      enabled: earnedContracts.length > 0,
      retry: 3,
      retryDelay: 1e3
    }
  });
  const rewards = useMemo(() => {
    if (!earnedAmounts || earnedContracts.length === 0) return [];
    const rewardList = [];
    earnedAmounts.forEach((amountData, index) => {
      const amount = amountData.result;
      const meta = earnedContracts[index]?.meta;
      if (!amount || !meta || amount === 0n) return;
      const tokenAddress = meta.token.toLowerCase();
      const tokenInfo = TOKEN_METADATA_CACHE[tokenAddress] || { symbol: "TOKEN", decimals: 18 };
      rewardList.push({
        address: meta.token,
        symbol: tokenInfo.symbol,
        decimals: tokenInfo.decimals,
        amount: amount.toString(),
        formattedAmount: formatUnits(amount, tokenInfo.decimals),
        type: meta.type,
        contractAddress: meta.contractAddress
      });
    });
    return rewardList;
  }, [earnedAmounts, earnedContracts]);
  const canClaim = rewards.length > 0;
  const refetch = useCallback(() => {
    refetchPools();
    refetchRewards();
  }, [refetchPools, refetchRewards]);
  const isLoading = poolsLoading || gaugesLoading || rewardContractsLoading || rewardsLoading || tokenAddressesLoading || earnedLoading;
  const error = poolsError || gaugesError || rewardContractsError || rewardsError || tokenAddressesError || earnedError;
  return {
    rewards,
    votedPools: rewardContracts.pools,
    totalValueUSD: "0",
    // Would need price feeds for accurate calculation
    canClaim,
    isLoading,
    error,
    refetch
  };
}
export function formatRewardAmount(amount, decimals) {
  const value = parseFloat(formatUnits(BigInt(amount), decimals));
  if (value === 0) return "0";
  if (value < 1e-3) return "< 0.001";
  if (value < 1) return value.toFixed(6);
  if (value < 100) return value.toFixed(4);
  return value.toFixed(2);
}
export function groupRewardsByType(rewards) {
  return {
    fees: rewards.filter((r) => r.type === "fee"),
    bribes: rewards.filter((r) => r.type === "bribe")
  };
}
export function getUniqueRewardContracts(rewards) {
  const feeContracts = /* @__PURE__ */ new Set();
  const bribeContracts = /* @__PURE__ */ new Set();
  rewards.forEach((reward) => {
    if (reward.type === "fee") {
      feeContracts.add(reward.contractAddress);
    } else {
      bribeContracts.add(reward.contractAddress);
    }
  });
  return {
    feeContracts: Array.from(feeContracts),
    bribeContracts: Array.from(bribeContracts)
  };
}
export function getRewardTokenArrays(fees, bribes) {
  return {
    feeTokens: fees.map((token) => token.address),
    bribeTokens: bribes.map((token) => token.address)
  };
}
