  const { token0: poolToken0, token1: poolToken1, isLoading: poolTokensLoading } = usePoolTokens(poolAddress);
  const defaultWETH = new Token(
    UniverseChainId.AbstractTestnet,
    "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d",
    18,
    "WETH",
    "Wrapped Ether"
  );
  const defaultUSDC = new Token(
    UniverseChainId.AbstractTestnet,
    "0x698f98aB816670692fa9DD8e1486ea0fd253e996",
    18,
    "USDC",
    "USD Coin"
  );
  const token0 = position?.currency0Amount?.currency || poolToken0 || (votedPools?.length ? defaultWETH : void 0);
