"use strict";
import { useState, useEffect } from "react";
import { Contract } from "@ethersproject/contracts";
import { useEthersProvider } from "hooks/useEthersProvider";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { Token } from "@uniswap/sdk-core";
const POOL_ABI = [
  "function token0() external view returns (address)",
  "function token1() external view returns (address)"
];
const ERC20_ABI = [
  "function symbol() external view returns (string)",
  "function decimals() external view returns (uint8)",
  "function name() external view returns (string)"
];
export function usePoolTokens(poolAddress) {
  const provider = useEthersProvider({ chainId: UniverseChainId.AbstractTestnet });
  const [tokenInfo, setTokenInfo] = useState({
    token0: void 0,
    token1: void 0,
    isLoading: false
  });
  useEffect(() => {
    async function fetchPoolTokens() {
      if (!poolAddress || !provider || poolAddress === "0x0000000000000000000000000000000000000000") {
        setTokenInfo({ token0: void 0, token1: void 0, isLoading: false });
        return;
      }
      setTokenInfo((prev) => ({ ...prev, isLoading: true }));
      try {
        console.log(`\u{1F50D} [POOL TOKENS] Fetching tokens for pool: ${poolAddress}`);
        const poolContract = new Contract(poolAddress, POOL_ABI, provider);
        const [token0Address, token1Address] = await Promise.all([
          poolContract.token0(),
          poolContract.token1()
        ]);
        console.log(`\u{1F50D} [POOL TOKENS] Found token addresses:`, { token0Address, token1Address });
        const [token0Data, token1Data] = await Promise.all([
          getTokenMetadata(token0Address, provider),
          getTokenMetadata(token1Address, provider)
        ]);
        const token0 = new Token(
          UniverseChainId.AbstractTestnet,
          token0Address,
          token0Data.decimals,
          token0Data.symbol,
          token0Data.name
        );
        const token1 = new Token(
          UniverseChainId.AbstractTestnet,
          token1Address,
          token1Data.decimals,
          token1Data.symbol,
          token1Data.name
        );
        console.log(`\u2705 [POOL TOKENS] Created tokens:`, {
          token0: `${token0.symbol} (${token0.address})`,
          token1: `${token1.symbol} (${token1.address})`
        });
        setTokenInfo({
          token0,
          token1,
          isLoading: false
        });
      } catch (error) {
        console.error(`\u274C [POOL TOKENS] Error fetching pool tokens for ${poolAddress}:`, error);
        setTokenInfo({
          token0: void 0,
          token1: void 0,
          isLoading: false
        });
      }
    }
    fetchPoolTokens();
  }, [poolAddress, provider]);
  return tokenInfo;
}
async function getTokenMetadata(tokenAddress, provider) {
  try {
    const tokenContract = new Contract(tokenAddress, ERC20_ABI, provider);
    const [symbol, decimals, name] = await Promise.all([
      tokenContract.symbol(),
      tokenContract.decimals(),
      tokenContract.name()
    ]);
    return { symbol, decimals, name };
  } catch (error) {
    console.warn(`\u26A0\uFE0F [POOL TOKENS] Failed to get metadata for token ${tokenAddress}:`, error);
    const knownTokens = {
      "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d": { symbol: "WETH", decimals: 18, name: "Wrapped Ether" },
      "0xb6313be1c20dc222199ec567951abc6b5b64dfd6": { symbol: "ABX", decimals: 18, name: "Aborean Token" },
      "0x698f98ab816670692fa9dd8e1486ea0fd253e996": { symbol: "USDC", decimals: 18, name: "USD Coin" }
    };
    return knownTokens[tokenAddress.toLowerCase()] || { symbol: "TOKEN", decimals: 18, name: "Unknown Token" };
  }
}
