"use strict";
import { useReadContracts } from "wagmi";
import { getContractAddress, getContractAbi, ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
export function useVotedLocks(locks) {
  const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const currentTimestamp = BigInt(Math.floor(Date.now() / 1e3));
  const contracts = locks.flatMap((lock) => [
    {
      address: voterAddress,
      abi: voterAbi,
      functionName: "lastVoted",
      args: [BigInt(lock.id)]
    },
    {
      address: voterAddress,
      abi: voterAbi,
      functionName: "usedWeights",
      args: [BigInt(lock.id)]
    },
    {
      address: voterAddress,
      abi: voterAbi,
      functionName: "epochStart",
      args: [currentTimestamp]
    }
  ]);
  const { data, isLoading } = useReadContracts({
    contracts,
    query: {
      enabled: locks.length > 0
    }
  });
  const votedLockIds = /* @__PURE__ */ new Set();
  if (data && !isLoading) {
    const epochStartIndex = contracts.length - 1;
    const currentEpochStart = data[epochStartIndex]?.result;
    locks.forEach((lock, index) => {
      const lastVotedIndex = index * 2;
      const usedWeightsIndex = index * 2 + 1;
      const lastVoted = data[lastVotedIndex]?.result;
      const usedWeights = data[usedWeightsIndex]?.result;
      if (lastVoted && currentEpochStart && usedWeights) {
        if (lastVoted >= currentEpochStart && usedWeights > 0n) {
          votedLockIds.add(lock.id);
        }
      }
    });
  }
  return {
    votedLockIds,
    isLoading,
    hasVoted: (lockId) => votedLockIds.has(lockId)
  };
}
